#!/usr/bin/env python3
"""FS3 v164 - M61 without the destroyer.

    M61       no Shivan destroyer any more (Silvio). Every Rakshasa that is
              destroyed comes back through the portal a quarter tougher
              than the one before, without end, so the Aeolus falls in the
              end. From 90 s a second line of them, as before.
    Missions  new: replace on a unit (comes back when destroyed, hull times
              the factor each time).
    Tests     wpnsim knows that the Dante comes with mission 61 rather
              than with points (it failed two checks since v163).

Needs v163. Edits src/30_waves.js in place, and writes the updated
fieldsim.js and wpnsim.js. Run assemble.py afterwards.
"""
import base64
import os
import sys

if "FLEET_TABS" not in open("src/70_ui.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v163 einspielen.")
if "EV_REPL" in open("src/30_waves.js", encoding="utf-8").read():
    sys.exit("Abbruch: v164 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)

rep('src/30_waves.js',
    "  // 61 is on this side of the Knossos, the same place as 55-60. The\n  // Shivans come through the portal and look round; the Aeolus stands\n  // guard with the player. She is lost in the end - the mission is how\n  // long she holds and what it costs them (Silvio).\n  61:{name:'The Reconnaissance', fac:'shivan', o:'clear', live:4, scene:'knossos',\n      portal:true, portalIn:true,\n      ziel:'COVER THE AEOLUS', u:[\n",
    "  // 61 is on this side of the Knossos, the same place as 55-60. The\n  // Shivans come through the portal and look round; the Aeolus stands\n  // guard with the player. She is lost in the end - the mission is how\n  // long she holds and what it costs them (Silvio). The Rakshasas keep\n  // coming, each tougher than the last, until she falls.\n  61:{name:'The Reconnaissance', fac:'shivan', o:'clear', live:4, scene:'knossos',\n      portal:true, portalIn:true,\n      ziel:'COVER THE AEOLUS', u:[\n")
